/* ================================================================
   PROJECT — App Patches (Clean Core)
   يحتوي فقط على:
     1. تصحيح رابط السيرفر → Cloudflare Worker
     2. الاشتراك الإجباري في القنوات
     3. تحسين قسم الإحالات
   تم حذف: مسابقات، سباق، دراجات، تعدين، مهام
   ================================================================ */

(function() {

/* ================================================================
   1. SERVER URL FIX — توجيه كل طلبات API للسيرفر الصحيح على Cloudflare
   ================================================================ */
(function patchServerUrl() {
  var WORKER_URL = 'https://silent-block-bedf.ahmedrabieharoun.workers.dev';

  // انتظر حتى يتاح window.api
  function waitForApi(n) {
    n = n || 0;
    var orig = window.api || window.callApi || window.apiCall;
    if (typeof orig !== 'function') {
      if (n < 40) setTimeout(function() { waitForApi(n + 1); }, 300);
      return;
    }
    if (orig.__cfPatched) return;

    // patch fetch globally to redirect /api to Cloudflare Worker
    var _origFetch = window.fetch;
    window.fetch = function(url, opts) {
      if (typeof url === 'string') {
        // Replace relative /api calls with the Cloudflare Worker URL
        if (url === '/api' || url === 'api' || url === './api') {
          url = WORKER_URL + '/api';
        }
        // Replace any localhost or staging references
        url = url.replace(/https?:\/\/localhost[:\d]*/g, WORKER_URL);
        url = url.replace(/https?:\/\/127\.0\.0\.1[:\d]*/g, WORKER_URL);
      }
      return _origFetch.apply(this, [url, opts]);
    };

    orig.__cfPatched = true;
    console.log('[CF Patch] API redirected to:', WORKER_URL);
  }

  setTimeout(function() { waitForApi(); }, 200);
})();


/* ================================================================
   2. FORCED CHANNEL SUBSCRIPTION — اشتراك إجباري قبل الاستخدام
   ================================================================ */
(function() {
  function buildModal(channels) {
    if (document.getElementById('forcedSubModal')) return;

    var css = ''
      + '#forcedSubBackdrop{position:fixed;inset:0;background:rgba(0,0,0,.45);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);z-index:9998;display:none}'
      + '#forcedSubModal{position:fixed;left:50%;bottom:0;transform:translateX(-50%);width:min(420px,98vw);max-height:80vh;overflow-y:auto;background:linear-gradient(180deg,#0d1424 0%,#0a0f1c 100%);border:1px solid rgba(212,175,55,.45);border-top-left-radius:20px;border-top-right-radius:20px;border-bottom-left-radius:0;border-bottom-right-radius:0;padding:14px 14px calc(14px + env(safe-area-inset-bottom,0px));z-index:9999;display:none;box-shadow:0 -8px 30px rgba(0,0,0,.7),0 0 28px rgba(212,175,55,.14);font-family:Fredoka,system-ui,sans-serif}'
      + '.fsub-crown{display:flex;justify-content:center;margin-bottom:4px;filter:drop-shadow(0 3px 10px rgba(212,175,55,.5))}'
      + '.fsub-crown svg{width:44px;height:32px}'
      + '#forcedSubModal h3{font-size:14px;font-weight:800;letter-spacing:1.4px;background:linear-gradient(180deg,#f5d77a,#c9a04a);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin:0 0 4px;text-align:center;text-transform:uppercase}'
      + '#forcedSubModal .fsub-sub{font-size:10.5px;color:rgba(232,232,245,.65);text-align:center;line-height:1.4;margin:0 4px 10px}'
      + '#forcedSubModal .fsub-sub b{color:#f5d77a;font-weight:700}'
      + '#forcedSubList{display:flex;flex-direction:column;gap:7px;margin-bottom:10px}'
      + '.fsub-row{display:flex;align-items:center;gap:9px;background:linear-gradient(180deg,rgba(20,28,46,.85),rgba(12,18,32,.85));border:1px solid rgba(80,100,140,.32);border-radius:11px;padding:8px 9px;position:relative;overflow:hidden}'
      + '.fsub-ico{width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0}'
      + '.fsub-ico.tg{background:radial-gradient(circle at 30% 30%,#3aaeff,#0a78d0);box-shadow:0 0 16px rgba(40,150,230,.5)}'
      + '.fsub-ico.pay{background:radial-gradient(circle at 30% 30%,#a26bff,#5b2bcc);box-shadow:0 0 16px rgba(140,90,230,.5)}'
      + '.fsub-ico svg{width:16px;height:16px;fill:#fff}'
      + '.fsub-text{flex:1;min-width:0}'
      + '.fsub-name{font-size:11.5px;font-weight:700;color:#fff;margin-bottom:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}'
      + '.fsub-desc{font-size:9px;color:rgba(200,210,230,.55);line-height:1.3}'
      + '.fsub-btn{display:inline-flex;align-items:center;gap:4px;background:transparent;color:#fff;border:1.2px solid rgba(255,255,255,.18);border-radius:8px;padding:5px 9px;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;white-space:nowrap;transition:all .2s}'
      + '.fsub-row.tg .fsub-btn{border-color:rgba(58,174,255,.5);color:#7cc6ff}'
      + '.fsub-row.pay .fsub-btn{border-color:rgba(162,107,255,.5);color:#c5a4ff}'
      + '.fsub-btn.joined{border-color:rgba(60,200,120,.55);color:#7cd99a;background:rgba(60,200,120,.08)}'
      + '#forcedSubCheck{width:100%;padding:10px;background:linear-gradient(180deg,#3a2810,#1a1208);border:1.3px solid rgba(212,175,55,.7);border-radius:11px;color:#f5d77a;font-size:11.5px;font-weight:800;cursor:pointer;box-shadow:0 0 14px rgba(212,175,55,.22),inset 0 1px 0 rgba(245,215,122,.16);font-family:inherit;display:flex;flex-direction:column;align-items:center;gap:1px;line-height:1.25}'
      + '#forcedSubCheck:disabled{opacity:.6;cursor:default}'
      + '.fsub-foot{display:flex;align-items:flex-start;justify-content:center;gap:5px;margin-top:8px;font-size:8.5px;color:rgba(170,180,200,.5);text-align:center;line-height:1.4;padding:0 4px}';

    var st = document.createElement('style');
    st.textContent = css;
    document.head.appendChild(st);

    var bd = document.createElement('div');
    bd.id = 'forcedSubBackdrop';

    var modal = document.createElement('div');
    modal.id = 'forcedSubModal';

    var crown = '<div class="fsub-crown"><svg viewBox="0 0 80 60" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="fsg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f5d77a"/><stop offset="1" stop-color="#b8861c"/></linearGradient></defs><path d="M5 30 Q20 22 32 30 L32 36 Q20 30 5 32 Z" fill="url(#fsg)" opacity=".9"/><path d="M75 30 Q60 22 48 30 L48 36 Q60 30 75 32 Z" fill="url(#fsg)" opacity=".9"/><path d="M28 18 L40 8 L52 18 L52 42 Q40 52 28 42 Z" fill="url(#fsg)" stroke="#8a6516" stroke-width="1"/><polygon points="40,18 43,26 51,26 45,31 47,39 40,34 33,39 35,31 29,26 37,26" fill="#1a1208"/></svg></div>';
    var foot = '<div class="fsub-foot"><span>We will verify your subscription automatically. You will get access right after verification.</span></div>';

    modal.innerHTML = crown
      + '<h3>Mandatory Subscription</h3>'
      + '<div class="fsub-sub">To use all features,<br>you <b>must</b> subscribe to the following channels</div>'
      + '<div id="forcedSubList"></div>'
      + '<button id="forcedSubCheck"><span>✅ I have subscribed to all channels</span><span style="font-size:9px;font-weight:500;color:rgba(245,215,122,.7)">Continue to use the app</span></button>'
      + foot;

    document.body.appendChild(bd);
    document.body.appendChild(modal);
  }

  function renderList(channels) {
    var list = document.getElementById('forcedSubList');
    if (!list) return;
    var tgSvg = '<svg viewBox="0 0 24 24"><path d="M9.78 18.65l.28-4.23 7.68-6.92c.34-.31-.07-.46-.52-.19L7.74 13.3 3.64 12c-.88-.25-.89-.86.2-1.3l15.97-6.16c.73-.33 1.43.18 1.15 1.3l-2.72 12.81c-.19.91-.74 1.13-1.5.71L12.6 16.3l-1.99 1.93c-.23.23-.42.42-.83.42z"/></svg>';
    var paySvg = '<svg viewBox="0 0 24 24"><path d="M21 7H3c-1.1 0-2 .9-2 2v8c0 1.1.9 2 2 2h18c1.1 0 2-.9 2-2V9c0-1.1-.9-2-2-2zm-3 8h-4v-2h4v2zm3-5H3V8h18v2z"/></svg>';
    var extSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>';

    list.innerHTML = channels.map(function(c) {
      var isPay = /pay|wallet|deposit|دفع/i.test(c.name || c.id || '');
      var cls   = isPay ? 'pay' : 'tg';
      var icon  = isPay ? paySvg : tgSvg;
      var name  = c.name || c.id || (isPay ? 'Payments Channel' : 'News Channel');
      var desc  = isPay ? 'Stay updated about payments and special deals.' : 'Get the latest news and important announcements.';
      var btn   = c.joined
        ? '<button class="fsub-btn joined" disabled>✓ Joined</button>'
        : '<button class="fsub-btn" onclick="window.open(\'' + (c.link || '#') + '\',\'_blank\')">' + extSvg + 'Subscribe</button>';
      return '<div class="fsub-row ' + cls + '" data-cid="' + c.id + '">'
        + '<div class="fsub-ico ' + cls + '">' + icon + '</div>'
        + '<div class="fsub-text"><div class="fsub-name">' + name + '</div><div class="fsub-desc">' + desc + '</div></div>'
        + btn + '</div>';
    }).join('');
  }

  function show(channels) {
    buildModal(channels);
    renderList(channels);
    document.getElementById('forcedSubBackdrop').style.display = 'block';
    document.getElementById('forcedSubModal').style.display = 'block';
    var btn = document.getElementById('forcedSubCheck');
    btn.onclick = function() {
      btn.disabled = true;
      btn.innerHTML = '<span>Checking…</span>';
      verifyForcedSub().then(function(res) {
        btn.disabled = false;
        btn.innerHTML = '<span>✅ I have subscribed to all channels</span><span style="font-size:9px;font-weight:500;color:rgba(245,215,122,.7)">Continue to use the app</span>';
        if (res && res.success) {
          hide();
          if (typeof showNotif === 'function') showNotif('✅ Verified! Welcome.', 's');
        } else {
          var chs = (res && res.data && res.data.channels) || channels.map(function(c) {
            return { id: c.id, name: c.name, link: c.link, joined: false };
          });
          renderList(chs);
          if (typeof showNotif === 'function') showNotif('❌ Please join all channels first', 'e');
        }
      });
    };
  }

  function hide() {
    var bd = document.getElementById('forcedSubBackdrop');
    var m  = document.getElementById('forcedSubModal');
    if (bd) bd.style.display = 'none';
    if (m)  m.style.display  = 'none';
  }

  function verifyForcedSub() {
    var fn = window.api || window.callApi || window.apiCall;
    if (typeof fn === 'function') {
      return Promise.resolve()
        .then(function() { return fn('verifyForcedSubscription', {}); })
        .then(function(data) { return { success: true, data: data || { joined: true } }; })
        .catch(function() {
          var initData = (window.Telegram && Telegram.WebApp && Telegram.WebApp.initData) || '';
          return fetch('https://silent-block-bedf.ahmedrabieharoun.workers.dev/api', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Authorization: initData ? ('Telegram ' + initData) : '' },
            body: JSON.stringify({ action: 'verifyForcedSubscription', data: {} }),
          }).then(function(r) { return r.json(); }).catch(function() { return { success: false }; });
        });
    }
    var initData = (window.Telegram && Telegram.WebApp && Telegram.WebApp.initData) || '';
    return fetch('https://silent-block-bedf.ahmedrabieharoun.workers.dev/api', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: initData ? ('Telegram ' + initData) : '' },
      body: JSON.stringify({ action: 'verifyForcedSubscription', data: {} }),
    }).then(function(r) { return r.json(); }).catch(function() { return { success: false }; });
  }

  function maybeShow() {
    try {
      var S = window.S || window.state || {};
      if (!S.user || !S._dataLoaded) { setTimeout(maybeShow, 1200); return; }
      if (S.user.hasJoinedChannels === true) { hide(); return; }
      var chs = S.forcedChannels || [];
      verifyForcedSub().then(function(res) {
        if (res && res.success && res.data && res.data.joined) {
          if (S.user) S.user.hasJoinedChannels = true;
          hide();
          return;
        }
        if (S.user) S.user.hasJoinedChannels = false;
        var list = (res && res.data && res.data.channels) || chs.map(function(c) {
          return { id: c.id, name: c.name, link: c.link, joined: false };
        });
        if (list && list.length) show(list);
      });
    } catch (_) {}
  }

  window.__checkForcedSub = maybeShow;
  setTimeout(maybeShow, 1500);
  setTimeout(maybeShow, 4000);
})();


/* ================================================================
   3. REFERRALS NOTE — تحسين نص شرح الإحالات
   ================================================================ */
(function patchReferralsText() {
  var LANGS = {
    ar: {
      heading: '👥 برنامج الإحالات',
      note: 'إحالتك تُحتسب عندما يودع صديقك أو يسحب من البوت. كلما زادت إحالاتك النشطة كلما حصلت على عمولة أكثر!',
    },
    en: {
      heading: '👥 Referral Program',
      note: 'Your referral becomes active when your friend makes a deposit or withdrawal. More active referrals = more commission earned!',
    },
    ru: {
      heading: '👥 Реферальная программа',
      note: 'Реферал активируется, когда друг делает депозит или вывод. Больше рефералов — больше заработок!',
    },
    es: {
      heading: '👥 Programa de referidos',
      note: 'Tu referido se activa cuando hace un depósito o retiro. ¡Más referidos activos = más comisiones!',
    },
    fr: {
      heading: '👥 Programme de parrainage',
      note: 'Votre parrainage devient actif quand votre ami fait un dépôt ou un retrait. Plus de parrainages = plus de commission!',
    },
  };

  function getLng() {
    try {
      var S = window.S || window.state || {};
      var l = (S.user && S.user.language) || 'en';
      return LANGS[l] ? l : 'en';
    } catch (_) { return 'en'; }
  }

  function inject() {
    var sec = document.getElementById('sectionReferrals') || document.querySelector('[id*="eferral"]');
    if (!sec) return;
    if (sec.querySelector('.raseen-ref-note')) return;
    var t = LANGS[getLng()];
    var div = document.createElement('div');
    div.className = 'raseen-ref-note';
    div.style.cssText = 'margin:14px 16px 2px;padding:13px 15px;border-radius:14px;background:rgba(124,179,66,.12);border:1px solid rgba(124,179,66,.3);';
    div.innerHTML = '<div style="font-size:14px;font-weight:800;color:#7cb342;margin-bottom:6px;">' + t.heading + '</div>'
      + '<div style="font-size:12px;color:rgba(255,255,255,.72);line-height:1.6;">' + t.note + '</div>';
    var inner = sec.querySelector('.sec-inner') || sec.querySelector('.sec-content') || sec;
    inner.insertBefore(div, inner.firstChild);
  }

  function tryInject(n) {
    n = n || 0;
    if (n > 20) return;
    var s = document.getElementById('sectionReferrals') || document.querySelector('[id*="eferral"]');
    if (s) { inject(); return; }
    setTimeout(function() { tryInject(n + 1); }, 500);
  }
  setTimeout(tryInject, 2200);

  // Re-inject when language changes
  (function watchLang() {
    var orig = window.api;
    if (typeof orig !== 'function') { setTimeout(watchLang, 400); return; }
    if (orig.__refNoteWrapped) return;
    orig.__refNoteWrapped = true;
    window.api = function(action, data) {
      var p = orig.apply(this, arguments);
      if (action === 'saveLanguage' && p && typeof p.then === 'function') {
        p.then(function() {
          var o = document.querySelector('.raseen-ref-note');
          if (o) o.remove();
          setTimeout(inject, 200);
        }).catch(function() {});
      }
      return p;
    };
    window.api.__refNoteWrapped = true;
  })();
})();


/* ================================================================
   4. PERFORMANCE — تحسين الأداء على الأجهزة الضعيفة
   ================================================================ */
(function patchLowEndPerf() {
  var mem  = navigator.deviceMemory || 4;
  var cpus = navigator.hardwareConcurrency || 4;
  var isLowEnd = (mem < 2 || cpus < 4);

  var gpuCss = '.ni { will-change: auto; transform: translateZ(0); }';
  var lowCss = isLowEnd ? [
    '.ni { transition: none !important; }',
    '#sectionHome, #sectionFinance { contain: content; }',
  ].join('\n') : '';

  var styleEl = document.createElement('style');
  styleEl.id = 'raseenPerfCss';
  styleEl.textContent = gpuCss + (lowCss ? '\n/* low-end */\n' + lowCss : '');
  document.head.appendChild(styleEl);

  // Passive touch listeners
  (function patchPassiveListeners() {
    var orig = EventTarget.prototype.addEventListener;
    if (orig.__raseenPassive) return;
    EventTarget.prototype.addEventListener = function(type, fn, opts) {
      if (type === 'touchstart' || type === 'touchmove' || type === 'wheel' || type === 'mousewheel') {
        if (typeof opts === 'boolean') opts = { capture: opts, passive: true };
        else if (!opts)               opts = { passive: true };
        else if (opts.passive === undefined) opts = Object.assign({}, opts, { passive: true });
      }
      return orig.call(this, type, fn, opts);
    };
    EventTarget.prototype.addEventListener.__raseenPassive = true;
  })();

  // requestIdleCallback shim for Safari
  if (!window.requestIdleCallback) {
    window.requestIdleCallback = function(cb) { return setTimeout(function() { cb({ timeRemaining: function() { return 20; }, didTimeout: false }); }, 1); };
    window.cancelIdleCallback = function(id) { clearTimeout(id); };
  }

  document.addEventListener('visibilitychange', function() {
    window._raseenHidden = document.hidden;
  });
})();

})(); // end main IIFE
